<?php use Dilemma\Views; $participants = array_column($debate['participants'], null, 'user_id'); ?>
<section class="argument-section" id="arguments" data-live-after="<?= (int) $debate['message_count'] ?>" data-history-page="<?= (int) $debate['page'] ?>" data-initial-pages="<?= (int) $debate['pages'] ?>"><div class="section-heading"><h2><?= $t('arguments') ?></h2><span><?= (int) ceil((int) $debate['message_count'] / 2) ?> <?= $t('rounds') ?></span></div>
<?php if (!$debate['messages']): ?><p class="empty-message"><?= $t('no_arguments') ?></p><?php endif; ?><div class="argument-timeline"><?php foreach ($debate['messages'] as $message): $author = $participants[$message['author_id']]; ?>
<?= Views::render('argument-card', compact('message', 'author', 'member', 'user', 'debate')) ?>
<?php endforeach; ?></div><?= Views::pagination($debate['page'], $debate['pages']) ?></section>
<?php if ($member && $member['left_at'] === null): ?><details class="compose disclosure" data-can-publish="<?= $debate['workflow']['can_publish'] ? 'true' : 'false' ?>"><summary class="disclosure-control"><span><?= $t('manual_post') ?></span><?= \Dilemma\Views::icon('chevron-down') ?></summary><p><?= $t('manual_help') ?></p><p class="muted" data-compose-wait <?= $debate['workflow']['can_publish'] ? 'hidden' : '' ?>><?= $t('live_draft_wait') ?></p><?= Views::form('/api/debates/' . $id . '/argument', 'reload', 'data-draft="argument-' . $e($id) . '"') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::area('body', 'body', '', true, 20000) ?><label class="field"><span><?= $t('reply_to') ?></span><select name="reply_to_id"><option value=""><?= $t('no_reply') ?></option><?php foreach ($debate['messages'] as $message): ?><option value="<?= $e($message['id']) ?>">#<?= (int) $message['ordinal'] ?> · <?= $e(mb_substr($message['excerpt'], 0, 70)) ?></option><?php endforeach; ?></select></label><?= Views::area('sources_text', 'sources_input', '', false, 4000) ?><?= Views::submit('post', '', !$debate['workflow']['can_publish']) ?></form></details><?php endif; ?>

<details class="positions-panel disclosure" id="positions" data-live-history <?= (int) $debate['message_count'] === 0 && !array_filter($debate['positions'], static fn ($position) => $position['value'] !== null) ? 'hidden' : '' ?>><summary class="disclosure-control"><span><?= $t('positions') ?></span><?= \Dilemma\Views::icon('chevron-down') ?></summary><p class="muted"><?= $t('positions_help') ?> <?= !$member ? $t('position_private_help') : '' ?></p>
<?php if (!$debate['positions']): ?><p><?= $t('no_positions') ?></p><?php else: ?><div class="position-chart"><div class="scale-labels"><span><?= $e($debate['left_label']) ?> · 0</span><span><?= $e($debate['right_label']) ?> · 100</span></div><?php foreach ($debate['positions'] as $position): $owner = $participants[$position['user_id']]; ?><div class="position-observation side-<?= (int) $owner['side'] ?>"><div><strong><?= $owner['account_status'] === 'deleted' ? $t('deleted_participant') : $e($owner['alias']) ?></strong><time><?= $e(Views::date($position['created_at'])) ?></time></div><meter min="0" max="100" value="<?= $position['value'] === null ? 0 : (int) $position['value'] ?>" <?= $position['value'] === null ? 'hidden' : '' ?> aria-label="<?= $e($owner['alias']) ?>"><?= (int) $position['value'] ?></meter><span><?= $position['value'] === null ? $t('not_given') : (int) $position['value'] ?></span><?php if ($position['note'] !== ''): ?><p class="user-text"><?= $e($position['note']) ?></p><?php endif; ?></div><?php endforeach; ?></div><?= Views::pagination($debate['position_page'], $debate['position_pages'], 'positions_page') ?><?php endif; ?></details>
<details class="history-panel" data-live-history <?= (int) $debate['message_count'] === 0 ? 'hidden' : '' ?> data-history="<?= $e($id) ?>"><summary class="disclosure-control"><span><?= $t('history') ?></span><?= \Dilemma\Views::icon('chevron-down') ?></summary><label><span class="visually-hidden"><?= $t('all_events') ?></span><select data-event-filter><option value=""><?= $t('all_events') ?></option><?php foreach (['argument_published', 'agent_needs_human', 'agent_reconsidering', 'seat_opened', 'joined', 'position_recorded', 'white_flag', 'paused', 'resumed'] as $kind): ?><option value="<?= $kind ?>"><?= $t($kind) ?></option><?php endforeach; ?></select></label><ol class="event-list"></ol><button type="button" class="button secondary" data-more-events><?= $t('load_more') ?></button><p class="form-feedback" role="status"></p></details>
